function consensus(present: number[], clades: number[]): Tree {
  const tree = empty(count);
  const root = tree.next++;
  const all = present.filter((i) => i !== outgroup).reduce((mask, i) => mask | (2 ** i), 0);
  connect(tree, root, outgroup);
  function fill(node: number, container: number): void {
    const proper = clades.filter((c) => c !== container && contains(container, c));
    const maximal = proper.filter((c) => !proper.some((d) => c !== d && contains(d, c)));
    let covered = 0;
    for (const clade of maximal) {
      const child = tree.next++;
      connect(tree, node, child);
      covered |= clade;
      fill(child, clade);
    }
    for (const taxon of present) {
      if (taxon !== outgroup && container & (2 ** taxon) && !(covered & (2 ** taxon))) {
        connect(tree, node, taxon);
      }
    }
  }
  fill(root, all);
  return tree;
}
let random = numeric('seed');
const support = new Map<number, number>();
for (let b = 1; b <= replicates; b++) {
  const weights = Array<number>(length).fill(0);
  for (let c = 0; c < length; c++) {
    random = (48271 * random) % 2147483647;
    weights[random % length]++;
  }
  const tree = neighborJoining(matrix(count, tally(sequences, weights), model, replacement), taxa);
  const clades = splits(tree, outgroup);
  for (const mask of clades) support.set(mask, (support.get(mask) ?? 0) + 1);
}
const majority = consensus(
  taxa,
  [...support].filter(([, n]) => 2 * n > replicates).map(([mask]) => mask),
);
export function empty(next: number): Tree {
  return { edges: new Map(), next, negative: 0 };
}
export function connect(tree: Tree, a: number, b: number, length = 0): void {
  if (!tree.edges.has(a)) tree.edges.set(a, new Map());
  if (!tree.edges.has(b)) tree.edges.set(b, new Map());
  tree.edges.get(a)!.set(b, length);
  tree.edges.get(b)!.set(a, length);
}
export function rooted(tree: Tree, outgroup: number): Rooted {
  const root = tree.edges.get(outgroup)!.keys().next().value!;
  const children = new Map<number, number[]>();
  const parent = new Map<number, number | null>([[root, null]]);
  const nodes = [root];
  for (let i = 0; i < nodes.length; i++) {
    const v = nodes[i];
    const next = [...tree.edges.get(v)!.keys()].filter((c) => c !== parent.get(v));
    children.set(v, next);
    for (const c of next) {
      parent.set(c, v);
      nodes.push(c);
    }
  }
  const masks = new Map<number, number>();
  for (const v of [...nodes].reverse()) {
    const child = children.get(v)!;
    masks.set(
      v,
      child.length
        ? child.reduce((mask, c) => mask | (v === root && c === outgroup ? 0 : masks.get(c)!), 0)
        : 2 ** v,
    );
  }
  return { root, children, parent, masks, nodes };
}
export function splits(tree: Tree, outgroup: number): Set<number> {
  const view = rooted(tree, outgroup);
  return new Set(
    view.nodes
      .filter((v) => v !== view.root && view.children.get(v)!.length > 0)
      .map((v) => view.masks.get(v)!),
  );
}
